argv:
out=$(mktemp); err=$(mktemp); trap 'rm -f "$out" "$err"' EXIT; printf '%s\n' '{"v":1,"seq":1,"type":"event","event":"show"}' '{"v":1,"seq":2,"type":"event","event":"click"}' '{"v":1,"seq":3,"type":"event","event":"hide"}' | timeout 20s cargo run --quiet --locked -p inir-companiond >"$out" 2>"$err"; rc=$?; [ "$rc" -eq 0 ] || exit 41; python - "$out" <<'PY'
import json,sys
with open(sys.argv[1],encoding='utf-8') as fh: rows=[json.loads(line) for line in fh if line.strip()]
if len(rows)!=4: raise SystemExit(42)
if any(row.get('v')!=1 or row.get('type')!='state' for row in rows): raise SystemExit(43)
seq=[row.get('seq') for row in rows]
if seq!=sorted(seq) or len(set(seq))!=len(seq): raise SystemExit(44)
if rows[0].get('visibility')!='hidden': raise SystemExit(45)
if rows[1].get('visibility')!='present': raise SystemExit(46)
if rows[2].get('mood')!='happy' or rows[2].get('pulse',0)<=0.7: raise SystemExit(47)
if rows[3].get('visibility')!='hidden': raise SystemExit(48)
PY
